#!/usr/bin/env node
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import process from "node:process";
import zlib from "node:zlib";
import { fileURLToPath } from "node:url";

const PATCH = "pfotentechnik-weekly-research-findings-32.0.0";
const scriptFile = fileURLToPath(import.meta.url);
const payload = [{"path":"apps/pfotentechnik/research/research.json","gzip":""},{"path":"apps/pfotentechnik/src/content/pages/smarte-haustiertechnik.md","gzip":""},{"path":"apps/pfotentechnik/src/content/pages/gps-tracker.md","gzip":""},{"path":"apps/pfotentechnik/src/content/pages/katzenklappe-einbauen.md","gzip":""},{"path":"apps/pfotentechnik/src/content/pages/trinkbrunnen-fuer-mehrere-katzen.md","gzip":""},{"path":"apps/pfotentechnik/src/content/pages/trinkmenge-katze-messen.md","gzip":""},{"path":"apps/pfotentechnik/src/content/pages/haustierkameras.md","gzip":""},{"path":"apps/pfotentechnik/src/content/pages/automatische-katzentoiletten.md","gzip":""},{"path":"apps/pfotentechnik/src/content/comparisons/beste-gps-tracker-fuer-hunde.md","gzip":""},{"path":"apps/pfotentechnik/src/content/comparisons/beste-gps-tracker-fuer-katzen.md","gzip":""},{"path":"apps/pfotentechnik/src/content/comparisons/gps-tracker-ohne-abo.md","gzip":""},{"path":"apps/pfotentechnik/src/content/comparisons/katzenklappen-mit-app-und-beuteerkennung.md","gzip":""},{"path":"apps/pfotentechnik/src/content/comparisons/beste-haustierkameras.md","gzip":""},{"path":"apps/pfotentechnik/src/content/comparisons/beste-automatische-katzentoiletten.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/tractive-cat-6-mini.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/tractive-dog-6.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/tractive-dog-6-xl.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/weenect-xs.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/weenect-xt.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/onlycat-mikrochip-katzenklappe.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/petlibro-scout-smart-camera.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/furbo-360-hundekamera.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/enabot-ebo-air-2.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/litter-robot-5-pro.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/petkit-purobot-max-pro-2.md","gzip":""},{"path":"apps/pfotentechnik/src/content/products/neakasa-m1-plus.md","gzip":""},{"path":"apps/pfotentechnik/src/content/manufacturers/weenect.md","gzip":""},{"path":"apps/pfotentechnik/src/content/manufacturers/furbo.md","gzip":""},{"path":"apps/pfotentechnik/src/content/manufacturers/enabot.md","gzip":""},{"path":"apps/pfotentechnik/src/content/manufacturers/whisker.md","gzip":""},{"path":"apps/pfotentechnik/src/content/manufacturers/neakasa.md","gzip":""},{"path":"apps/pfotentechnik/src/assets/images/products/petlibro-scout-smart-camera/hero.webp","gzip":""},{"path":"apps/pfotentechnik/src/assets/images/products/furbo-360-hundekamera/hero.webp","gzip":""},{"path":"apps/pfotentechnik/src/assets/images/products/enabot-ebo-air-2/hero.webp","gzip":""},{"path":"apps/pfotentechnik/src/assets/images/products/litter-robot-5-pro/hero.webp","gzip":""},{"path":"apps/pfotentechnik/src/assets/images/products/petkit-purobot-max-pro-2/hero.webp","gzip":""},{"path":"apps/pfotentechnik/src/assets/images/products/neakasa-m1-plus/hero.webp","gzip":""}];
const findingIds = ["tractive-health-monitoring-2026-refresh","weenect-plus-serenity-2026-refresh","petkit-eversweet-ultra-2026-refresh","onlycat-installation-guides-2026-refresh","haustierkameras-cluster-phase-1","automatische-katzentoiletten-cluster-phase-1"];

function findRoot(start) {
  let current = path.resolve(start);
  while (true) {
    if (fs.existsSync(path.join(current, "package.json")) && fs.existsSync(path.join(current, "apps", "pfotentechnik"))) return current;
    const parent = path.dirname(current);
    if (parent === current) throw new Error(`[${PATCH}] Repository-Root nicht gefunden.`);
    current = parent;
  }
}

const root = findRoot(process.cwd());
const stamp = new Date().toISOString().replace(/[:.]/g, "-");
const backupDir = path.join(root, ".patch-backups", `${PATCH}-${stamp}`);
const originals = new Map();
const changed = [];
const sha = (value) => crypto.createHash("sha256").update(value).digest("hex");

function backup(file) {
  if (originals.has(file)) return;
  const previous = fs.existsSync(file) ? fs.readFileSync(file) : null;
  originals.set(file, previous);
  if (previous === null) return;
  const target = path.join(backupDir, path.relative(root, file));
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, previous);
}

function rollback() {
  for (const [file, previous] of [...originals.entries()].reverse()) {
    if (previous === null) fs.rmSync(file, { force: true });
    else {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, previous);
    }
  }
}

try {
  for (const item of payload) {
    const target = path.resolve(root, item.path);
    if (target !== path.join(root, item.path) || !target.startsWith(root + path.sep)) throw new Error(`[${PATCH}] Ungültiger Zielpfad: ${item.path}`);
    const intended = zlib.gunzipSync(Buffer.from(item.gzip, "base64"));
    const current = fs.existsSync(target) ? fs.readFileSync(target) : null;
    if (current && sha(current) === sha(intended)) continue;
    backup(target);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    const temporary = `${target}.${process.pid}.tmp`;
    fs.writeFileSync(temporary, intended);
    fs.renameSync(temporary, target);
    changed.push(item.path);
  }

  for (const item of payload) {
    const intended = zlib.gunzipSync(Buffer.from(item.gzip, "base64"));
    const actual = fs.readFileSync(path.join(root, item.path));
    if (sha(actual) !== sha(intended)) throw new Error(`[${PATCH}] Hashprüfung fehlgeschlagen: ${item.path}`);
  }

  const research = JSON.parse(fs.readFileSync(path.join(root, "apps/pfotentechnik/research/research.json"), "utf8"));
  for (const id of findingIds) {
    const finding = research.items.find((item) => item.id === id);
    if (!finding || finding.status !== "implemented") throw new Error(`[${PATCH}] Finding nicht abgeschlossen: ${id}`);
  }

  console.log(changed.length
    ? `[${PATCH}] ${changed.length} Dateien aktualisiert. Backup: ${backupDir}`
    : `[${PATCH}] No-op: Repository ist bereits auf dem Zielstand.`);
  console.log(`[${PATCH}] Hash- und Research-Validierung erfolgreich. Installer: ${path.relative(root, scriptFile)}`);
} catch (error) {
  rollback();
  console.error(`[${PATCH}] Fehler; Änderungen wurden zurückgerollt.`);
  throw error;
}
